{"status":"edit","missing_fact":"","edits":[{"path":"logic.hpp","hash":"2e573d8fc185bc56965eb4f9313f700abf6349d1979e627b95be447a0edaca53","old":"inline std::vector<int> unique(std::vector<int> values) { return values; }","new":"inline std::vector<int> unique(std::vector<int> values) {
    std::unordered_set<int> seen;
    std::vector<int> result;
    for (int value : values) {
        if (seen.insert(value).second) {
            result.push_back(value);
        }
    }
    return result;
}"}]}
